static TEST_COUNTER: AtomicU64 = AtomicU64::new(0);

fn unique_id(prefix: &str) -> String {
    let counter = TEST_COUNTER.fetch_add(1, Ordering::Relaxed);
    let nanos = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .expect("the system clock must be after the Unix epoch")
        .as_nanos();
    format!("{prefix}-{nanos}-{counter}")
}

async fn enroll_repository(database_url: &str, tenant_id: &str, repository_id: &str, unique: &str) {
    let seed: [u8; 32] = Sha256::digest(format!("key-{unique}").as_bytes()).into();
    let signing_key = SigningKey::from_bytes(&seed);
    let public_key = signing_key.verifying_key().to_bytes();
    let request_id = format!("request-{unique}");
    let node_id = format!("node-{unique}");
    let fingerprint = public_key_fingerprint(&public_key);
    let submission = EnrollmentSubmission {
        request_id: request_id.clone(),
        tenant_id: tenant_id.to_string(),
        repository_id: repository_id.to_string(),
        proposed_node_id: node_id.clone(),
        display_name: "Knowledge API integration node".to_string(),
        public_key: public_key.to_vec(),
        public_key_fingerprint: fingerprint.clone(),
        requested_capabilities: vec!["synchronize".to_string()],
        created_at: "2026-01-01T00:00:00Z".to_string(),
        expires_at: "2030-01-01T00:00:00Z".to_string(),
    };
    let request = ActivationChallengeRequest {
        request_id,
        tenant_id: tenant_id.to_string(),
        repository_id: repository_id.to_string(),
        proposed_node_id: node_id,
        public_key_fingerprint: fingerprint.clone(),
    };
    let mut enrollment = EnrollmentStore::connect(database_url)
        .await
        .expect("connect enrollment store");
    enrollment
        .submit(&submission)
        .await
        .expect("submit enrollment");
    enrollment
        .approve(&EnrollmentApproval {
            request_id: submission.request_id.clone(),
            tenant_id: tenant_id.to_string(),
            repository_id: repository_id.to_string(),
            public_key_fingerprint: fingerprint.clone(),
            approved_capabilities: submission.requested_capabilities.clone(),
            approved_by: "knowledge-api-integration-administrator".to_string(),
        })
        .await
        .expect("approve enrollment");
    let nonce: [u8; 32] = Sha256::digest(format!("nonce-{unique}").as_bytes()).into();
    let challenge = enrollment
        .issue_challenge(&request, &nonce, SystemTime::now())
        .await
        .expect("issue enrollment challenge");
    let signature = signing_key.sign(&activation_challenge_bytes(
        &challenge.nonce,
        &request.request_id,
        &request.tenant_id,
        &request.repository_id,
        &request.proposed_node_id,
        &request.public_key_fingerprint,
    ));
    enrollment
        .activate(
            &EnrollmentActivation {
                request,
                nonce: challenge.nonce,
                signature: signature.to_bytes().to_vec(),
            },
            &format!("receipt-{unique}"),
            &format!("signing-key-{unique}"),
            SystemTime::now(),
        )
        .await
        .expect("activate enrollment");
}

async fn application(database_url: &str, tenant_id: &str) -> axum::Router {
    let knowledge = Arc::new(
        KnowledgeStore::connect(database_url)
            .await
            .expect("connect Knowledge store"),
    );
    let fleet = Arc::new(
        FleetStore::connect(database_url)
            .await
            .expect("connect Fleet store"),
    );
    knowledge_routes(KnowledgeApiState::new(
        knowledge,
        fleet,
        Arc::<str>::from(tenant_id.to_string()),
    ))
}

async fn body_json(response: axum::response::Response) -> Value {
    let body = to_bytes(response.into_body(), 1_048_576)
        .await
        .expect("read Bridge response body");
    serde_json::from_slice(&body).expect("parse Bridge JSON response")
}

fn record_request(tenant_id: &str, repository_id: &str, content: &str) -> RecordKnowledgeRequest {
    RecordKnowledgeRequest {
        tenant_id: tenant_id.to_string(),
        repository_id: repository_id.to_string(),
        content: content.to_string(),
        source_ref: Some("receipt:knowledge-lifecycle".to_string()),
        recorded_by: Some("node:knowledge-producer".to_string()),
        reach_node_ids: vec!["artifact:crates/ackplane-server/src/knowledge_store.rs".to_string()],
        reach_goal_id: Some("goal:ackplane-federation-service".to_string()),
        half_life_hours: 72.0,
        embedding: None,
    }
}

#[tokio::test]
async fn knowledge_history_exposes_lifecycle_provenance_without_cross_tenant_data() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let unique = unique_id("knowledge-api");
    let tenant_id = format!("tenant-{unique}");
    let repository_id = format!("repository-{unique}");
    let foreign_tenant_id = format!("foreign-tenant-{unique}");
    let foreign_repository_id = format!("foreign-repository-{unique}");
    enroll_repository(&database_url, &tenant_id, &repository_id, &unique).await;
    enroll_repository(
        &database_url,
        &foreign_tenant_id,
        &foreign_repository_id,
        &format!("foreign-{unique}"),
    )
    .await;
    let knowledge = KnowledgeStore::connect(&database_url)
        .await
        .expect("connect Knowledge store");
    let active = knowledge
        .record(record_request(
            &tenant_id,
            &repository_id,
            "active knowledge statement",
        ))
        .await
        .expect("record active knowledge");
    knowledge
        .reconfirm(
            &tenant_id,
            &repository_id,
            &active.knowledge_id,
            "evidence:corroborated",
            "node:knowledge-reviewer",
            SystemTime::now(),
        )
        .await
        .expect("reconfirm active knowledge")
        .expect("active knowledge must reconfirm");
    let retired = knowledge
        .record(record_request(
            &tenant_id,
            &repository_id,
            "retired knowledge statement",
        ))
        .await
        .expect("record retired knowledge");
    assert!(knowledge
        .retire(
            &tenant_id,
            &repository_id,
            &retired.knowledge_id,
            "contradicted by later evidence",
            "node:knowledge-retirer",
        )
        .await
        .expect("retire knowledge"));

    let app = application(&database_url, &tenant_id).await;
    let all = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{repository_id}/knowledge/history?limit=10&state=all"
                ))
                .body(Body::empty())
                .expect("build all-history request"),
        )
        .await
        .expect("serve all-history request");
    assert_eq!(all.status(), StatusCode::OK);
    let all = body_json(all).await;
    assert_eq!(all["effective_limit"], json!(10));
    assert_eq!(all["state_filter"], json!("all"));
    let entries = all["entries"].as_array().expect("entries are an array");
    assert_eq!(entries.len(), 2);
    let active_entry = entries
        .iter()
        .find(|entry| entry["knowledge_id"] == active.knowledge_id)
        .expect("active knowledge history entry");
    assert_eq!(active_entry["lifecycle"], json!("active"));
    assert_eq!(
        active_entry["recorded_by"],
        json!("node:knowledge-producer")
    );
    assert_eq!(
        active_entry["reach_goal_id"],
        json!("goal:ackplane-federation-service")
    );
    assert_eq!(active_entry["reach_count"], json!(1));
    assert_eq!(
        active_entry["last_reconfirmed_by"],
        json!("node:knowledge-reviewer")
    );
    assert_eq!(
        active_entry["last_reconfirmation_evidence_ref"],
        json!("evidence:corroborated")
    );
    assert!(active_entry["last_reconfirmed_at_seconds"].is_number());
    // Reach is provenance, so it is named rather than only counted -- bounded,
    // and still read-only. `reach_count` keeps describing the whole set.
    assert_eq!(
        active_entry["reach_node_ids"],
        json!(["artifact:crates/ackplane-server/src/knowledge_store.rs"])
    );
    assert_eq!(active_entry["reach_truncated"], json!(false));
    let retired_entry = entries
        .iter()
        .find(|entry| entry["knowledge_id"] == retired.knowledge_id)
        .expect("retired knowledge history entry");
    assert_eq!(retired_entry["lifecycle"], json!("retired"));
    assert_eq!(retired_entry["retired_by"], json!("node:knowledge-retirer"));
    assert_eq!(
        retired_entry["retired_reason"],
        json!("contradicted by later evidence")
    );
    assert!(retired_entry["retired_at_seconds"].is_number());

    let active_only = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{repository_id}/knowledge/history?limit=10&state=active"
                ))
                .body(Body::empty())
                .expect("build active-history request"),
        )
        .await
        .expect("serve active-history request");
    assert_eq!(active_only.status(), StatusCode::OK);
    assert_eq!(
        body_json(active_only).await["entries"]
            .as_array()
            .map(Vec::len),
        Some(1)
    );

    let retired_only = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{repository_id}/knowledge/history?limit=10&state=retired"
                ))
                .body(Body::empty())
                .expect("build retired-history request"),
        )
        .await
        .expect("serve retired-history request");
    assert_eq!(retired_only.status(), StatusCode::OK);
    assert_eq!(
        body_json(retired_only).await["entries"]
            .as_array()
            .map(Vec::len),
        Some(1)
    );

    let bounded = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{repository_id}/knowledge/history?limit=1&state=all"
                ))
                .body(Body::empty())
                .expect("build bounded-history request"),
        )
        .await
        .expect("serve bounded-history request");
    assert_eq!(bounded.status(), StatusCode::OK);
    let bounded = body_json(bounded).await;
    assert_eq!(bounded["effective_limit"], json!(1));
    assert_eq!(bounded["entries"].as_array().map(Vec::len), Some(1));

    let foreign = app
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{foreign_repository_id}/knowledge/history?limit=10"
                ))
                .body(Body::empty())
                .expect("build foreign-history request"),
        )
        .await
        .expect("serve foreign-history request");
    assert_eq!(foreign.status(), StatusCode::NOT_FOUND);
}

#[tokio::test]
async fn revalidation_queue_classifies_active_records_and_stays_within_its_tenant() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let unique = unique_id("knowledge-revalidation-api");
    let tenant_id = format!("tenant-{unique}");
    let repository_id = format!("repository-{unique}");
    let foreign_tenant_id = format!("foreign-tenant-{unique}");
    let foreign_repository_id = format!("foreign-repository-{unique}");
    enroll_repository(&database_url, &tenant_id, &repository_id, &unique).await;
    enroll_repository(
        &database_url,
        &foreign_tenant_id,
        &foreign_repository_id,
        &format!("foreign-{unique}"),
    )
    .await;
    let knowledge = KnowledgeStore::connect(&database_url)
        .await
        .expect("connect Knowledge store");

    let current = knowledge
        .record(record_request(&tenant_id, &repository_id, "still current"))
        .await
        .expect("record current knowledge");
    knowledge
        .activate(
            &tenant_id,
            &repository_id,
            &current.knowledge_id,
            "human:reviewer",
            None,
            SystemTime::now(),
        )
        .await
        .expect("activate current knowledge");

    let contradicted = knowledge
        .record(record_request(&tenant_id, &repository_id, "later refuted"))
        .await
        .expect("record contradicted knowledge");
    knowledge
        .activate(
            &tenant_id,
            &repository_id,
            &contradicted.knowledge_id,
            "human:reviewer",
            None,
            SystemTime::now(),
        )
        .await
        .expect("activate contradicted knowledge");
    knowledge
        .record_evidence_reference(
            ackplane_server::knowledge_store::RecordKnowledgeEvidenceReferenceRequest {
                tenant_id: tenant_id.clone(),
                repository_id: repository_id.clone(),
                knowledge_id: contradicted.knowledge_id.clone(),
                kind: ackplane_server::knowledge_store::KnowledgeEvidenceReferenceKind::Validation,
                reference_ref: "evidence:refuted-by-a-later-run".to_string(),
                polarity: ackplane_server::knowledge_store::KnowledgeEvidencePolarity::Contradicts,
                recorded_by: "human:reviewer".to_string(),
            },
            SystemTime::now(),
        )
        .await
        .expect("record contradicting evidence");

    let app = application(&database_url, &tenant_id).await;
    let unfiltered = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{repository_id}/knowledge/revalidation-queue?limit=10"
                ))
                .body(Body::empty())
                .expect("build revalidation-queue request"),
        )
        .await
        .expect("serve revalidation-queue request");
    assert_eq!(unfiltered.status(), StatusCode::OK);
    let unfiltered = body_json(unfiltered).await;
    assert_eq!(unfiltered["classification_filter"], Value::Null);
    let entries = unfiltered["entries"].as_array().expect("entries array");
    assert_eq!(
        entries.len(),
        1,
        "the still-current record must be excluded"
    );
    let entry = &entries[0];
    assert_eq!(entry["knowledge_id"], json!(contradicted.knowledge_id));
    assert_eq!(entry["classification"], json!("contradicted"));
    assert_eq!(entry["content"], json!("later refuted"));
    assert!(entry["effective_weight"].as_f64().unwrap() > 0.99);

    let filtered_out = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{repository_id}/knowledge/revalidation-queue?classification=overdue_for_revalidation"
                ))
                .body(Body::empty())
                .expect("build filtered revalidation-queue request"),
        )
        .await
        .expect("serve filtered revalidation-queue request");
    assert_eq!(filtered_out.status(), StatusCode::OK);
    assert_eq!(
        body_json(filtered_out).await["entries"]
            .as_array()
            .map(Vec::len),
        Some(0)
    );

    let bad_classification = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{repository_id}/knowledge/revalidation-queue?classification=unknown"
                ))
                .body(Body::empty())
                .expect("build bad-classification request"),
        )
        .await
        .expect("serve bad-classification request");
    assert_eq!(bad_classification.status(), StatusCode::BAD_REQUEST);

    let foreign = app
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{foreign_repository_id}/knowledge/revalidation-queue"
                ))
                .body(Body::empty())
                .expect("build foreign revalidation-queue request"),
        )
        .await
        .expect("serve foreign revalidation-queue request");
    assert_eq!(foreign.status(), StatusCode::NOT_FOUND);
}
